import json
import math
import statistics
import sys
from pathlib import Path

out = Path(sys.argv[1])
dates = ["2024-03-04", "2024-03-05", "2024-03-06", "2024-03-07", "2024-03-08", "2024-03-11"]
closes = {
    "ACME": [182.5, 185.25, 183.1, 179.4, 181.75, 184.2],
    "BOLT": [41.2, 41.65, 42.05, 42.3, 42.9, 43.35],
}
tickers = sorted(closes)
prices = {"dates": dates, "tickers": tickers, "closes": closes}

rets = {
    t: [math.log(c[i] / c[i - 1]) for i in range(1, len(c))] for t, c in closes.items()
}
returns = {"base_date": dates[0], "dates": dates[1:], "tickers": tickers, "values": rets}
w = 2
vol = {
    t: [None if i < w else statistics.stdev(r[i - w : i]) * math.sqrt(252) for i in range(len(r))]
    for t, r in rets.items()
}
vols = {"returns": returns, "window": w, "annualized": True, "values": vol}


def summary(t):
    r = rets[t]
    ann_ret = 252 * statistics.fmean(r)
    ann_vol = math.sqrt(252) * statistics.stdev(r)
    return {
        "ticker": t,
        "ann_return": ann_ret,
        "ann_vol": ann_vol,
        "sharpe": 0.0 if ann_vol == 0 else ann_ret / ann_vol,
        "last_vol": vol[t][-1],
    }


def drawdown(t):
    wealth = 1.0
    peak, peak_d = 1.0, dates[0]
    best = (0.0, dates[0], dates[0])
    for d, r in zip(dates[1:], rets[t]):
        wealth *= math.exp(r)
        if wealth > peak:
            peak, peak_d = wealth, d
        dd = wealth / peak - 1
        if dd < best[0]:
            best = (dd, peak_d, d)
    return {"ticker": t, "depth": best[0], "peak_date": best[1], "trough_date": best[2]}


raw = []
for d in dates[:4]:
    for t in tickers:
        raw.append({"date": d, "ticker": t, "close": closes[t][dates.index(d)]})
raw[5]["close"] = None  # 2024-03-06 BOLT left blank
raw = [raw[1], raw[0], *raw[2:]]  # file order is not sorted

csv = "date,ticker,close\n" + "".join(
    f"{d},{t},{closes[t][i]}\n" for i, d in enumerate(dates) for t in tickers
)
sums = [summary(t) for t in tickers]
dds = [drawdown(t) for t in tickers]
rows = [
    {**s, "max_drawdown": dd["depth"], "peak_date": dd["peak_date"], "trough_date": dd["trough_date"]}
    for s, dd in zip(sums, dds)
]

files = {
    "mdata.RawRow": {"rows": raw},
    "mdata.Prices": prices,
    "risk.Returns": returns,
    "risk.VolSeries": vols,
    "risk.TickerSummary": sums[0],
    "risk.Drawdown": {"drawdowns": dds},
    "risk.Report": {"path": "risk_report.json", "rows": rows},
    "mdata.load_prices": {"csv": csv, "tickers": None, "prices": prices},
    "risk.vol_series": {"csv": csv, "window": w, "tickers": None, "vol": vols},
}
for name, payload in files.items():
    (out / name).mkdir(parents=True, exist_ok=True)
    (out / name / "sample.json").write_text(json.dumps(payload, indent=2) + "\n")
print(json.dumps(dds), json.dumps(sums[0]))

